"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[8110],{1587(e,t,n){n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>l,default:()=>h,frontMatter:()=>d,metadata:()=>a,toc:()=>u});const a=JSON.parse('{"id":"part2-backend-platform-security/background-tasks-and-retries","title":"Background Jobs, Idempotency, and Retries in FastAPI","description":"The concurrency chapter kept independent HTTP requests from blocking one another. This chapter handles a different problem: work that should outlive the request itself. We will move document ingestion into a job, make...","source":"@site/docs/part2-backend-platform-security/05-background-tasks-and-retries.mdx","sourceDirName":"part2-backend-platform-security","slug":"/part2-backend-platform-security/05-background-tasks-and-retries","permalink":"/tutorials/part2-backend-platform-security/05-background-tasks-and-retries","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":5,"frontMatter":{"title":"Background Jobs, Idempotency, and Retries in FastAPI","slug":"/part2-backend-platform-security/05-background-tasks-and-retries","description":"The concurrency chapter kept independent HTTP requests from blocking one another. This chapter handles a different problem: work that should outlive the request itself. We will move document ingestion into a job, make...","sidebar_label":"6. Background tasks and retries","pagination_label":"6. Background tasks and retries","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"5. Concurrency and user isolation","permalink":"/tutorials/part2-backend-platform-security/04-concurrency-user-isolation"},"next":{"title":"7. SSO, OAuth 2.0, and OIDC primer","permalink":"/tutorials/part2-backend-platform-security/06-sso-oauth2-oidc-primer"}}');var r=n(4848),o=n(8453),i=n(8172);const s=JSON.parse('{"sourcePath":"part2-backend-platform-security/05-background-tasks-and-retries.html","route":"/part2-backend-platform-security/05-background-tasks-and-retries","kind":"chapter","partId":"part2","partLabel":"Part II - Backend, Platform & Security","accent":"teal","heading":"Background Jobs, Idempotency, and Retries in FastAPI","title":"Background Jobs, Idempotency, and Retries in FastAPI","description":"The concurrency chapter kept independent HTTP requests from blocking one another. This chapter handles a different problem: work that should outlive the request itself. We will move document ingestion into a job, make...","readingMinutes":8,"bodyClass":"","normalizeMath":false,"toc":[{"id":"1-why-slow-work-should-not-run-inside-the-request","label":"1) Why slow work should not run inside the request"},{"id":"2-separate-best-effort-background-callbacks-from-durable-jobs","label":"2) Separate best-effort background callbacks from durable jobs"},{"id":"3-first-implementation-see-the-complete-interaction-with-backgroundtasks","label":"3) First implementation: see the complete interaction with BackgroundTasks"},{"id":"4-return-job-state-without-crossing-tenant-boundaries","label":"4) Return job state without crossing tenant boundaries"},{"id":"5-idempotency-means-one-logical-effect-not-merely-one-http-response","label":"5) Idempotency means one logical effect, not merely one HTTP response"},{"id":"6-retry-only-failures-that-can-plausibly-succeed-later","label":"6) Retry only failures that can plausibly succeed later"},{"id":"7-retry-steps-not-an-opaque-whole-workflow","label":"7) Retry steps, not an opaque whole workflow"},{"id":"8-durable-production-pattern-transaction-queue-worker","label":"8) Durable production pattern: transaction, queue, worker"},{"id":"9-failure-cancellation-and-dead-letter-handling","label":"9) Failure, cancellation, and dead-letter handling"},{"id":"10-observability-and-operational-controls","label":"10) Observability and operational controls"}],"html":"<p class=\\"lead\\">The concurrency chapter kept independent HTTP requests from\\nblocking one another. This chapter handles a different problem: work that\\nshould outlive the request itself. We will move document ingestion into a job,\\nmake job creation safe to retry, retry only transient downstream failures, and\\npreserve tenant identity from submission through completion.</p>\\n\\n<div class=\\"tr-note\\">\\n  <strong>The target interaction</strong>\\n  <code>POST /ingest</code> accepts work quickly and returns\\n  <code>202 Accepted</code> with a <code>job_id</code>. A worker performs the\\n  expensive extraction, embedding, and indexing. The client polls\\n  <code>GET /jobs/{job_id}</code> or receives a notification later.\\n</div>\\n\\n<h2 id=\\"1-why-slow-work-should-not-run-inside-the-request\\">1) Why slow work should not run inside the request</h2>\\n\\n<p>A normal HTTP request has a limited time budget. A reverse proxy, load\\nbalancer, browser, or mobile client may time out even though the server is\\nstill extracting a document. If the client retries, the server may start the\\nsame expensive operation twice.</p>\\n\\n<p>Document ingestion is a good running example because it usually contains\\nseveral independently fallible steps:</p>\\n\\n<ol>\\n  <li>Persist the upload or object reference.</li>\\n  <li>Extract and normalize text.</li>\\n  <li>Split text into chunks.</li>\\n  <li>Call an embedding service.</li>\\n  <li>Write vectors and metadata to an index.</li>\\n  <li>Mark the document ready for retrieval.</li>\\n</ol>\\n\\n<p>The request should record the intent to perform those steps, not remain open\\nuntil every step finishes.</p>\\n\\n<div class=\\"figure-card\\">\\n  <h3 id=\\"visual-request-lifecycle-and-job-lifecycle-are-different\\">Visual: request lifecycle and job lifecycle are different</h3>\\n  <svg class=\\"viz\\" viewBox=\\"0 0 980 290\\" role=\\"img\\" aria-label=\\"HTTP request creates a durable job processed by a worker\\">\\n    <defs>\\n      <marker id=\\"job-arrow\\" viewBox=\\"0 0 10 10\\" refX=\\"9\\" refY=\\"5\\" markerWidth=\\"8\\" markerHeight=\\"8\\" orient=\\"auto\\">\\n        <path d=\\"M0 0 L10 5 L0 10 z\\" class=\\"accentFill\\"></path>\\n      </marker>\\n      <marker id=\\"job-arrow-purple\\" viewBox=\\"0 0 10 10\\" refX=\\"9\\" refY=\\"5\\" markerWidth=\\"8\\" markerHeight=\\"8\\" orient=\\"auto\\">\\n        <path d=\\"M0 0 L10 5 L0 10 z\\" class=\\"accent2Fill\\"></path>\\n      </marker>\\n    </defs>\\n\\n    <rect x=\\"22\\" y=\\"74\\" width=\\"150\\" height=\\"94\\" rx=\\"14\\" class=\\"box2\\"></rect>\\n    <text x=\\"97\\" y=\\"110\\" text-anchor=\\"middle\\" class=\\"title\\">Client</text>\\n    <text x=\\"97\\" y=\\"138\\" text-anchor=\\"middle\\" class=\\"muted\\">POST /ingest</text>\\n\\n    <rect x=\\"232\\" y=\\"74\\" width=\\"180\\" height=\\"94\\" rx=\\"14\\" class=\\"box\\"></rect>\\n    <text x=\\"322\\" y=\\"110\\" text-anchor=\\"middle\\" class=\\"title\\">FastAPI</text>\\n    <text x=\\"322\\" y=\\"138\\" text-anchor=\\"middle\\" class=\\"muted\\">validate + enqueue</text>\\n\\n    <rect x=\\"472\\" y=\\"32\\" width=\\"190\\" height=\\"94\\" rx=\\"14\\" class=\\"box2\\"></rect>\\n    <text x=\\"567\\" y=\\"68\\" text-anchor=\\"middle\\" class=\\"title\\">Job store / queue</text>\\n    <text x=\\"567\\" y=\\"96\\" text-anchor=\\"middle\\" class=\\"muted\\">queued, attempt 0</text>\\n\\n    <rect x=\\"722\\" y=\\"32\\" width=\\"230\\" height=\\"94\\" rx=\\"14\\" class=\\"box\\"></rect>\\n    <text x=\\"837\\" y=\\"68\\" text-anchor=\\"middle\\" class=\\"title\\">Worker</text>\\n    <text x=\\"837\\" y=\\"96\\" text-anchor=\\"middle\\" class=\\"muted\\">extract \u2192 embed \u2192 index</text>\\n\\n    <rect x=\\"472\\" y=\\"184\\" width=\\"190\\" height=\\"76\\" rx=\\"14\\" class=\\"box2\\"></rect>\\n    <text x=\\"567\\" y=\\"216\\" text-anchor=\\"middle\\" class=\\"title\\">Job status</text>\\n    <text x=\\"567\\" y=\\"242\\" text-anchor=\\"middle\\" class=\\"muted\\">succeeded / failed</text>\\n\\n    <line x1=\\"172\\" y1=\\"121\\" x2=\\"232\\" y2=\\"121\\" class=\\"accent\\" stroke-width=\\"2\\" marker-end=\\"url(#job-arrow)\\"></line>\\n    <line x1=\\"412\\" y1=\\"102\\" x2=\\"472\\" y2=\\"82\\" class=\\"accent\\" stroke-width=\\"2\\" marker-end=\\"url(#job-arrow)\\"></line>\\n    <line x1=\\"662\\" y1=\\"79\\" x2=\\"722\\" y2=\\"79\\" class=\\"accent2\\" stroke-width=\\"2\\" marker-end=\\"url(#job-arrow-purple)\\"></line>\\n    <path d=\\"M837 126 C820 190 720 222 662 222\\" class=\\"accent2\\" stroke-width=\\"2\\" marker-end=\\"url(#job-arrow-purple)\\"></path>\\n    <path d=\\"M232 142 C188 206 132 212 96 168\\" class=\\"accent\\" stroke-width=\\"2\\" marker-end=\\"url(#job-arrow)\\"></path>\\n\\n    <text x=\\"322\\" y=\\"58\\" text-anchor=\\"middle\\" class=\\"muted\\">persist atomically</text>\\n    <text x=\\"164\\" y=\\"230\\" text-anchor=\\"middle\\" class=\\"muted\\">202 + job_id immediately</text>\\n  </svg>\\n</div>\\n\\n<h2 id=\\"2-separate-best-effort-background-callbacks-from-durable-jobs\\">2) Separate best-effort background callbacks from durable jobs</h2>\\n\\n<p>FastAPI\'s <code>BackgroundTasks</code> schedules a callable after the\\nresponse is sent. It is useful for short, non-critical work such as a small\\naudit write or cache cleanup when losing that work is acceptable.</p>\\n\\n<p>It is not a durable queue. The callback runs in the application process. A\\nrestart, deployment, crash, autoscaling event, or process termination can lose\\nthe task. Long callbacks also consume the same application\'s resources.</p>\\n\\n<table>\\n  <thead>\\n    <tr><th>Work type</th><th>Appropriate mechanism</th><th>Reason</th></tr>\\n  </thead>\\n  <tbody>\\n    <tr><td>Short, best-effort action after a response</td><td>FastAPI <code>BackgroundTasks</code></td><td>Simple and local; loss is acceptable.</td></tr>\\n    <tr><td>Document ingestion, email delivery, webhook, media processing</td><td>Durable queue plus worker</td><td>Survives restarts and supports retries, visibility, and dead-letter handling.</td></tr>\\n    <tr><td>Multi-step workflow with waits or compensation</td><td>Workflow engine or orchestrator</td><td>Persists step state and long-running control flow.</td></tr>\\n    <tr><td>Periodic work</td><td>Scheduler that enqueues a durable job</td><td>Separates schedule ownership from execution.</td></tr>\\n  </tbody>\\n</table>\\n\\n<p>Cloud Tasks, Pub/Sub with a subscriber, Celery or RQ with a durable broker,\\nand managed workflow services are common choices. The exact product matters\\nless than the guarantees you require: persistence, delivery semantics, retry\\npolicy, visibility timeout or lease, concurrency control, and a dead-letter\\npath.</p>\\n\\n<h2 id=\\"3-first-implementation-see-the-complete-interaction-with-backgroundtasks\\">3) First implementation: see the complete interaction with <code>BackgroundTasks</code></h2>\\n\\n<p>The following in-memory version is deliberately small. It demonstrates the\\nHTTP contract, idempotency key, identity propagation, and state transitions.\\nThe production section immediately afterward replaces its unsafe storage\\nassumptions.</p>\\n\\n<pre><code class=\\"language-python\\">from threading import Lock\\nfrom typing import Annotated, Literal\\nfrom uuid import uuid4\\nimport time\\n\\nfrom fastapi import BackgroundTasks, Depends, FastAPI, Header, HTTPException, status\\nfrom pydantic import BaseModel, Field\\n\\napp = FastAPI()\\n\\nclass Identity(BaseModel):\\n    tenant_id: str\\n    user_id: str\\n\\ndef get_identity() -&gt; Identity:\\n    # Teaching stand-in. Production verifies a bearer token and maps claims.\\n    return Identity(tenant_id=\\"tenant-acme\\", user_id=\\"user-123\\")\\n\\nclass IngestRequest(BaseModel):\\n    document_uri: str\\n\\nclass IngestResponse(BaseModel):\\n    job_id: str\\n    status: Literal[\\"queued\\"]\\n\\nclass JobView(BaseModel):\\n    job_id: str\\n    document_uri: str\\n    status: Literal[\\"queued\\", \\"running\\", \\"succeeded\\", \\"failed\\"]\\n    error: str | None = None\\n\\n# Teaching-only process memory. Production uses a database + durable queue.\\nJOBS: dict[str, dict] = {}\\nIDEMPOTENCY: dict[tuple[str, str], IngestResponse] = {}\\nSTORE_LOCK = Lock()\\n\\ndef ingest_job(job_id: str) -&gt; None:\\n    try:\\n        JOBS[job_id][\\"status\\"] = \\"running\\"\\n        time.sleep(2)  # stand-in for extract -&gt; embed -&gt; index\\n        JOBS[job_id][\\"status\\"] = \\"succeeded\\"\\n    except Exception as exc:\\n        JOBS[job_id][\\"status\\"] = \\"failed\\"\\n        JOBS[job_id][\\"error\\"] = str(exc)\\n\\n@app.post(\\n    \\"/ingest\\",\\n    response_model=IngestResponse,\\n    status_code=status.HTTP_202_ACCEPTED,\\n)\\ndef ingest(\\n    payload: IngestRequest,\\n    background: BackgroundTasks,\\n    identity: Annotated[Identity, Depends(get_identity)],\\n    idempotency_key: Annotated[str, Header(alias=\\"Idempotency-Key\\")],\\n) -&gt; IngestResponse:\\n    store_key = (identity.tenant_id, idempotency_key)\\n\\n    # The lock makes the teaching store\'s check-and-create atomic in one process.\\n    with STORE_LOCK:\\n        if previous := IDEMPOTENCY.get(store_key):\\n            return previous\\n\\n        job_id = str(uuid4())\\n        response = IngestResponse(job_id=job_id, status=\\"queued\\")\\n\\n        JOBS[job_id] = {\\n            \\"job_id\\": job_id,\\n            \\"tenant_id\\": identity.tenant_id,\\n            \\"user_id\\": identity.user_id,\\n            \\"document_uri\\": payload.document_uri,\\n            \\"status\\": \\"queued\\",\\n            \\"error\\": None,\\n        }\\n        IDEMPOTENCY[store_key] = response\\n\\n    background.add_task(ingest_job, job_id)\\n    return response</code></pre>\\n\\n<p>The client supplies the same idempotency key every time it retries the same\\nlogical submission:</p>\\n\\n<pre><code class=\\"language-http\\">POST /ingest HTTP/1.1\\nHost: api.example.com\\nAuthorization: Bearer &lt;access-token&gt;\\nIdempotency-Key: 9c2f9f2f-9bd8-4d1e-8b45-4a338f89f9a0\\nContent-Type: application/json\\n\\n{\\"document_uri\\": \\"gs://tenant-acme/inbox/report.pdf\\"}</code></pre>\\n\\n<pre><code class=\\"language-http\\">HTTP/1.1 202 Accepted\\nContent-Type: application/json\\nLocation: /jobs/b6d0b2e4-3fbd-4ab7-87fb-02f911c4c21e\\n\\n{\\"job_id\\": \\"b6d0b2e4-3fbd-4ab7-87fb-02f911c4c21e\\", \\"status\\": \\"queued\\"}</code></pre>\\n\\n<div class=\\"tr-warn\\">\\n  <strong>Concurrency detail:</strong> \u201clook up the key, then insert\u201d must be one\\n  atomic operation. A Python dictionary and lock only protect one teaching\\n  process. In production, enforce a database unique constraint on a key such as\\n  <code>(tenant_id, operation, idempotency_key)</code> and commit the\\n  idempotency record with the job record in one transaction.\\n</div>\\n\\n<h2 id=\\"4-return-job-state-without-crossing-tenant-boundaries\\">4) Return job state without crossing tenant boundaries</h2>\\n\\n<p>A <code>job_id</code> is an identifier, not authorization. Every status read,\\ncancel operation, artifact download, and retry must check the tenant from the\\nverified request identity against the tenant stored on the job.</p>\\n\\n<pre><code class=\\"language-python\\">@app.get(\\"/jobs/{job_id}\\", response_model=JobView)\\ndef get_job(\\n    job_id: str,\\n    identity: Annotated[Identity, Depends(get_identity)],\\n) -&gt; JobView:\\n    job = JOBS.get(job_id)\\n\\n    # Returning 404 for both cases avoids revealing another tenant\'s job IDs.\\n    if job is None or job[\\"tenant_id\\"] != identity.tenant_id:\\n        raise HTTPException(status_code=404, detail=\\"Job not found\\")\\n\\n    return JobView.model_validate(job)</code></pre>\\n\\n<p>For user-owned jobs, add a <code>user_id</code> check too. For shared\\ntenant jobs, authorize by role or permission. The worker must also scope every\\ndatabase read, object-store path, vector-index namespace, and emitted event\\nusing the job\'s persisted tenant context.</p>\\n\\n<h2 id=\\"5-idempotency-means-one-logical-effect-not-merely-one-http-response\\">5) Idempotency means one logical effect, not merely one HTTP response</h2>\\n\\n<p>An idempotency record should normally retain:</p>\\n\\n<ul>\\n  <li>tenant or principal scope;</li>\\n  <li>operation name and idempotency key;</li>\\n  <li>a hash of the normalized request payload;</li>\\n  <li>the created resource or job ID;</li>\\n  <li>the original status code and response body;</li>\\n  <li>creation time, expiry policy, and processing state.</li>\\n</ul>\\n\\n<p>If the same key arrives with a different payload hash, reject it with a\\nconflict rather than silently returning an unrelated response. Keep the\\nretention period at least as long as the maximum client retry window.</p>\\n\\n<div class=\\"tr-note\\">\\n  <strong>Delivery semantics</strong>\\n  Most practical queues are <em>at least once</em>: a worker may receive the\\n  same message more than once. \u201cExactly once\u201d business behavior is therefore\\n  built from idempotent consumers, unique constraints, conditional writes, and\\n  deduplication, not from assuming the queue will never redeliver.\\n</div>\\n\\n<h2 id=\\"6-retry-only-failures-that-can-plausibly-succeed-later\\">6) Retry only failures that can plausibly succeed later</h2>\\n\\n<p>Retries help transient faults such as timeouts, connection resets, rate\\nlimits, and temporary service unavailability. They make permanent faults worse\\nby adding latency and load.</p>\\n\\n<table>\\n  <thead><tr><th>Failure</th><th>Retry?</th><th>Typical handling</th></tr></thead>\\n  <tbody>\\n    <tr><td>Timeout, connection reset, HTTP 502/503/504</td><td>Usually</td><td>Bounded exponential backoff with jitter.</td></tr>\\n    <tr><td>HTTP 429</td><td>Usually</td><td>Respect <code>Retry-After</code>; apply rate limiting.</td></tr>\\n    <tr><td>HTTP 401</td><td>Only after credential refresh</td><td>Refresh once; repeated 401 is permanent for this attempt.</td></tr>\\n    <tr><td>HTTP 403</td><td>No</td><td>Fix authorization or policy.</td></tr>\\n    <tr><td>HTTP 400/422 or schema validation error</td><td>No</td><td>Correct the request or quarantine the message.</td></tr>\\n    <tr><td>Not found</td><td>Context dependent</td><td>Retry only when eventual consistency is expected and bounded.</td></tr>\\n  </tbody>\\n</table>\\n\\n<h3 id=\\"a-small-retry-helper-with-exponential-backoff-and-jitter\\">A small retry helper with exponential backoff and jitter</h3>\\n\\n<pre><code class=\\"language-python\\">from collections.abc import Callable\\nfrom random import uniform\\nfrom time import sleep\\nfrom typing import TypeVar\\n\\nT = TypeVar(\\"T\\")\\n\\nclass TransientError(Exception):\\n    pass\\n\\ndef retry_transient(\\n    operation: Callable[[], T],\\n    *,\\n    attempts: int = 4,\\n    base_delay: float = 0.25,\\n    max_delay: float = 4.0,\\n) -&gt; T:\\n    last_error: TransientError | None = None\\n\\n    for attempt in range(attempts):\\n        try:\\n            return operation()\\n        except TransientError as exc:\\n            last_error = exc\\n            if attempt == attempts - 1:\\n                break\\n\\n            cap = min(max_delay, base_delay * (2 ** attempt))\\n            sleep(uniform(0, cap))  # full jitter prevents synchronized retries\\n\\n    assert last_error is not None\\n    raise last_error</code></pre>\\n\\n<p>A production HTTP client library or queue normally provides retry hooks.\\nUse those rather than maintaining a general retry framework yourself, but keep\\nthe same policy questions explicit: which exceptions, how many attempts, what\\ndeadline, whether the operation is idempotent, and how <code>Retry-After</code>\\nis handled.</p>\\n\\n<h2 id=\\"7-retry-steps-not-an-opaque-whole-workflow\\">7) Retry steps, not an opaque whole workflow</h2>\\n\\n<p>The original ingestion example called two flaky dependencies. Keep those\\nsteps independently observable and idempotent:</p>\\n\\n<pre><code class=\\"language-python\\">def call_search_index(job: dict) -&gt; None:\\n    # Use a deterministic document ID so a retry overwrites/upserts,\\n    # rather than creating duplicate indexed documents.\\n    ...\\n\\ndef call_embedding_service(job: dict) -&gt; list[list[float]]:\\n    # A pure request is safe to repeat; cache by content hash when useful.\\n    ...\\n\\ndef run_ingestion(job_id: str) -&gt; None:\\n    job = load_job(job_id)\\n    mark_running(job_id)\\n\\n    try:\\n        vectors = retry_transient(lambda: call_embedding_service(job))\\n        retry_transient(lambda: call_search_index({**job, \\"vectors\\": vectors}))\\n        mark_succeeded(job_id)\\n    except TransientError as exc:\\n        mark_failed(job_id, code=\\"retries_exhausted\\", detail=str(exc))\\n        raise</code></pre>\\n\\n<p>Checkpointing matters for expensive workflows. If extraction succeeded but\\nindexing failed, a retry should resume at indexing when possible rather than\\nrepeat the upload and extraction. Store step state and immutable input\\nreferences so a worker can reconstruct the attempt.</p>\\n\\n<h2 id=\\"8-durable-production-pattern-transaction-queue-worker\\">8) Durable production pattern: transaction, queue, worker</h2>\\n\\n<p>The central reliability problem is a dual write: what if the API commits the\\njob row but crashes before publishing to the queue, or publishes to the queue\\nbut fails before committing the job row?</p>\\n\\n<p>The <strong>transactional outbox</strong> pattern solves this when the job\\ndatabase and broker cannot share one transaction:</p>\\n\\n<ol>\\n  <li>In one database transaction, insert the job, idempotency record, and an outbox event.</li>\\n  <li>Commit once.</li>\\n  <li>A relay publishes unsent outbox rows to the queue.</li>\\n  <li>After publish succeeds, mark the outbox row sent.</li>\\n  <li>The worker consumes idempotently because relay or broker delivery can repeat.</li>\\n</ol>\\n\\n<pre><code class=\\"language-text\\">API transaction\\n  \u251c\u2500 jobs(job_id, tenant_id, status=\\"queued\\", ...)\\n  \u251c\u2500 idempotency(tenant_id, key, request_hash, job_id, ...)\\n  \u2514\u2500 outbox(event_id, type=\\"ingest.requested\\", payload, sent_at=NULL)\\n\\nOutbox relay \u2192 durable queue \u2192 worker \u2192 status/artifacts</code></pre>\\n\\n<p>Some managed task queues let the API create the task directly with a\\ndeterministic task name and provide adequate deduplication for your use case.\\nDocument the chosen guarantee rather than assuming every queue behaves the\\nsame.</p>\\n\\n<h2 id=\\"9-failure-cancellation-and-dead-letter-handling\\">9) Failure, cancellation, and dead-letter handling</h2>\\n\\n<p>A job state machine should make terminal and non-terminal states explicit.\\nA practical minimum is <code>queued</code>, <code>running</code>,\\n<code>succeeded</code>, <code>failed</code>, and <code>canceled</code>. Add\\n<code>retry_scheduled</code> or step-level states only when operators need\\nthem.</p>\\n\\n<ul>\\n  <li>After retries are exhausted, move or route the message to a dead-letter queue and mark the job failed with a stable error code.</li>\\n  <li>Make cancellation cooperative: set <code>cancel_requested</code> and let workers stop between safe steps.</li>\\n  <li>Do not expose internal stack traces to clients; preserve them in restricted logs.</li>\\n  <li>Define whether operators can replay a failed job and whether replay creates a new attempt or a new job.</li>\\n  <li>Use a lease or visibility timeout so abandoned work can be redelivered after a worker crash.</li>\\n</ul>\\n\\n<h2 id=\\"10-observability-and-operational-controls\\">10) Observability and operational controls</h2>\\n\\n<p>Every log, metric, and trace should carry <code>job_id</code>,\\n<code>tenant_id</code>, attempt number, step name, and correlation or trace ID.\\nUseful metrics include queue age, processing duration, retry count, success\\nrate, dead-letter volume, and jobs stuck in a non-terminal state.</p>\\n\\n<div class=\\"summary-box\\">\\n  <h3 id=\\"what-to-remember\\">What to remember</h3>\\n  <ul>\\n    <li><code>BackgroundTasks</code> is for short best-effort callbacks, not durable ingestion.</li>\\n    <li>Return <code>202 Accepted</code> and a job resource when work continues after the request.</li>\\n    <li>Make the idempotency check and job creation atomic and tenant-scoped.</li>\\n    <li>Assume at-least-once delivery and make workers and side effects idempotent.</li>\\n    <li>Retry transient failures with bounded backoff and jitter; do not retry validation or authorization failures.</li>\\n    <li>Persist tenant and user context on the job and re-authorize every status or artifact read.</li>\\n    <li>Use an outbox or equivalent mechanism when database state and queue publication must agree.</li>\\n  </ul>\\n</div>\\n\\n<p class=\\"footer-note\\">The next chapter begins the authentication sequence. It\\nexplains how the request identity persisted on a job is established through\\nSSO, OAuth 2.0, and OpenID Connect.</p>"}'),d={title:"Background Jobs, Idempotency, and Retries in FastAPI",slug:"/part2-backend-platform-security/05-background-tasks-and-retries",description:"The concurrency chapter kept independent HTTP requests from blocking one another. This chapter handles a different problem: work that should outlive the request itself. We will move document ingestion into a job, make...",sidebar_label:"6. Background tasks and retries",pagination_label:"6. Background tasks and retries",hide_title:!0,hide_table_of_contents:!0},l=void 0,c={},u=[];function p(e){return(0,r.jsx)(i.A,{content:s})}function h(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(p,{...e})}):p()}}}]);